CREATE OR ALTER PROCEDURE [dbo].[uspShiftSwapRequest_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @RequesterEmployeeId UNIQUEIDENTIFIER = NULL
	, @TargetEmployeeId UNIQUEIDENTIFIER = NULL
	, @CurrentShiftAssignmentId UNIQUEIDENTIFIER = NULL
	, @ProposedShiftAssignmentId UNIQUEIDENTIFIER = NULL
	, @RequestStatus NVARCHAR(MAX) = NULL
	, @ApprovalRequestId UNIQUEIDENTIFIER = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[RequestNo]
			, t.[RequesterEmployeeId]
			, t.[TargetEmployeeId]
			, t.[CurrentShiftAssignmentId]
			, t.[ProposedShiftAssignmentId]
			, t.[Reason]
			, t.[RequestStatus]
			, t.[ApprovalRequestId]
			, t.[SubmittedAt]
			, t.[CreatedDate]
		FROM [dbo].[ShiftSwapRequest] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[RequestNo] LIKE CONCAT('%', @SearchText, '%'))
			AND (@RequesterEmployeeId IS NULL OR t.[RequesterEmployeeId] = @RequesterEmployeeId)
			AND (@TargetEmployeeId IS NULL OR t.[TargetEmployeeId] = @TargetEmployeeId)
			AND (@CurrentShiftAssignmentId IS NULL OR t.[CurrentShiftAssignmentId] = @CurrentShiftAssignmentId)
			AND (@ProposedShiftAssignmentId IS NULL OR t.[ProposedShiftAssignmentId] = @ProposedShiftAssignmentId)
			AND (ISNULL(@RequestStatus, '') = '' OR t.[RequestStatus] = @RequestStatus)
			AND (@ApprovalRequestId IS NULL OR t.[ApprovalRequestId] = @ApprovalRequestId)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestNo' THEN r.[RequestNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestNo' THEN r.[RequestNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requesterEmployeeId' THEN r.[RequesterEmployeeId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requesterEmployeeId' THEN r.[RequesterEmployeeId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'targetEmployeeId' THEN r.[TargetEmployeeId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'targetEmployeeId' THEN r.[TargetEmployeeId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'currentShiftAssignmentId' THEN r.[CurrentShiftAssignmentId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'currentShiftAssignmentId' THEN r.[CurrentShiftAssignmentId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'proposedShiftAssignmentId' THEN r.[ProposedShiftAssignmentId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'proposedShiftAssignmentId' THEN r.[ProposedShiftAssignmentId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'reason' THEN r.[Reason] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'reason' THEN r.[Reason] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestStatus' THEN r.[RequestStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestStatus' THEN r.[RequestStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approvalRequestId' THEN r.[ApprovalRequestId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approvalRequestId' THEN r.[ApprovalRequestId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'submittedAt' THEN r.[SubmittedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'submittedAt' THEN r.[SubmittedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
